static int32_t clar_fn_irXRecFieldAlign(int32_t cv_f) {
    int32_t cv_xk;
    cv_xk = 0;
    cv_xk = clar_fn_irFieldSlotXKind(cv_f);
    if ((((cv_xk == 3) || (cv_xk == 4)) || (cv_xk == 5)) || (cv_xk == 6)) {
        return 2;
    }
    return 1;
    return 0;
}

static int32_t clar_fn_irXRecFieldSize(int32_t cv_f) {
    int32_t cv_xk;
    cv_xk = 0;
    cv_xk = clar_fn_irFieldSlotXKind(cv_f);
    if ((cv_xk == 1) || (cv_xk == 2)) {
        return 1;
    }
    if (cv_xk == 3) {
        return 2;
    }
    if ((cv_xk == 4) || (cv_xk == 5)) {
        return 4;
    }
    if (cv_xk == 7) {
        return (clar_fn_irFieldSlotXN(cv_f) + 1);
    }
    if (cv_xk == 8) {
        return clar_fn_irFieldSlotXN(cv_f);
    }
    return clar_fn_irXRecSize(clar_fn_irFindRecordLayoutByName(clar_fn_irtName(clar_fn_irFieldSlotType(cv_f))));
    return 0;
}

static int32_t clar_fn_irXRecSize(int32_t cv_recIdx) {
    int32_t cv_f;
    cv_f = 0;
    int32_t cv_offset;
    cv_offset = 0;
    cv_offset = 0;
    cv_f = clar_fn_irRecordLayoutFieldsHead(cv_recIdx);
    while (1) {
        if (!((cv_f != (-(1))))) break;
        if ((clar_fn_irXRecFieldAlign(cv_f) == 2) && ((cv_offset % 2) != 0)) {
            cv_offset = (cv_offset + 1);
        }
        cv_offset = (cv_offset + clar_fn_irXRecFieldSize(cv_f));
        cv_f = clar_fn_irFieldSlotNext(cv_f);
    }
    if ((cv_offset % 2) != 0) {
        cv_offset = (cv_offset + 1);
    }
    return cv_offset;
    return 0;
}

